UPDATE character_profiles SET voice_lines_json=(SELECT json_group_array(json(value)) FROM (SELECT value FROM json_each(voice_lines_json) UNION ALL SELECT incoming.value FROM json_each('[{"id":"zh-Play_Vo_Char_NPC027_hstruck_002-take-2","title":"Сильный урон II · Запись 2","language":"Китайский","audioUrl":"/nte-meta/game-audio/3e3569761aac9799b3b9.ogg","sourceUrl":"","description":"Уф… нгх…\n\n(Сяочжэнь: Ах ты бандюга!)"},{"id":"zh-Play_Vo_Char_NPC027_struck_001-take-2","title":"Урон I · Запись 2","language":"Китайский","audioUrl":"/nte-meta/game-audio/8c67c7cf6bfbce27048d.ogg","sourceUrl":"","description":"……\n\n(Сяочжэнь: Время платить по счетам!)"},{"id":"en-Play_Vo_Char_NPC027_struck_002-take-2","title":"Урон II · Запись 2","language":"Английский","audioUrl":"/nte-meta/game-audio/c3e3eb36edcc7331592d.ogg","sourceUrl":"","description":"По мне попали…\n\n(Сяочжэнь: Тогда дай сдачи!)"},{"id":"en-Play_Vo_Char_NPC027_TeammateDown_001-take-2","title":"Поражен товарищ по команде – Ноль · Запись 2","language":"Английский","audioUrl":"/nte-meta/game-audio/39e5f26a9956fc70e4bb.ogg","sourceUrl":"","description":"Сигнал оценщика… пропал…\n\n(Сяочжэнь: Малявка! Соберись!)Сигнал оценщицы… пропал…\n\n(Сяочжэнь: Малявка! Соберись!)"},{"id":"ko-Play_Vo_Char_NPC027_weather_004-take-2","title":"Жарко · Запись 2","language":"Корейский","audioUrl":"/nte-meta/game-audio/3be55d2aca21c1cef2c7.ogg","sourceUrl":"","description":"Ну и жара… Вот бы обернуть Сяочжэнь вокруг шеи вместо шарфа, мне бы сразу полегчало… Сяо… чжэнь…\n\n(Сяочжэнь: Ни за что! Ни один призрак в такую жарищу не вылезет из своего телика!)"},{"id":"ko-Play_Vo_Char_NPC027_ug_003-take-2","title":"Вознесение персонажа III · Запись 2","language":"Корейский","audioUrl":"/nte-meta/game-audio/1e86c84c27d3360ed85f.ogg","sourceUrl":"","description":"Финальная эволюция Линко… Эм-м, во что бы мне эволюционировать… может, в Абсолютную Линко!\n\n(Сяочжэнь: Тебе никогда не бывает скучно…)"},{"id":"ja-Play_Vo_Char_NPC027_gift_003-take-2","title":"Подарок получен III · Запись 2","language":"Японский","audioUrl":"/nte-meta/game-audio/eb9e26fc8fb45c7ec154.ogg","sourceUrl":"","description":"О, безграничные дары природы!\n\n(Сяочжэнь: Эй, это от оценщика вообще-то, а не от матушки природы.)О, безграничные дары природы!\n\n(Сяочжэнь: Эй, это от оценщицы вообще-то, а не от матушки природы.)"},{"id":"ko-Play_Vo_Char_NPC027_hobby_001-take-2","title":"Хобби · Запись 2","language":"Корейский","audioUrl":"/nte-meta/game-audio/e1618b79ffa16160968f.ogg","sourceUrl":"","description":"У меня дома есть огромный шкаф, забитый дисками с фильмами. Каждый вечер я наугад выбираю один и смотрю вместе с Сяочжэнь. Я обожаю всякое про пришельцев и паранормальщину, а вот Сяочжэнь такое терпеть не может. Она всегда ворчит: зачем смотреть на фальшивые спецэффекты, если она сама — самый что ни на есть настоящий дух…\n\n(Сяочжэнь: Пф-ф! Если меня, злого духа, когда-нибудь возьмут на роль злодея, фильм сразу станет в тысячу раз страшнее!)"},{"id":"ja-Play_Vo_Char_NPC027_hp_001-take-2","title":"Низкий уровень здоровья I · Запись 2","language":"Японский","audioUrl":"/nte-meta/game-audio/00e357d18a7b54ace504.ogg","sourceUrl":"","description":"Надо… собраться…\n\n(Сяочжэнь: Малявка, держись!)"},{"id":"zh-Play_Vo_Char_NPC027_ug_003-take-2","title":"Вознесение персонажа III · Запись 2","language":"Китайский","audioUrl":"/nte-meta/game-audio/5919d9a60afb733a602a.ogg","sourceUrl":"","description":"Финальная эволюция Линко… Эм-м, во что бы мне эволюционировать… может, в Абсолютную Линко!\n\n(Сяочжэнь: Тебе никогда не бывает скучно…)"},{"id":"zh-Play_Vo_Char_NPC027_hp_003-take-2","title":"Низкий уровень здоровья III · Запись 2","language":"Китайский","audioUrl":"/nte-meta/game-audio/eeca40d6b8a6e9a6e749.ogg","sourceUrl":"","description":"(Сяочжэнь: Малявка, не подставляйся больше!)\n\nЯ… справлюсь!"},{"id":"ko-Play_Vo_Char_NPC027_hp_002-take-2","title":"Низкий уровень здоровья II · Запись 2","language":"Корейский","audioUrl":"/nte-meta/game-audio/8985c9295bb738c6edd2.ogg","sourceUrl":"","description":"(Сяочжэнь: Эй, плохо дело!)\n\nЭто ещё… не конец!"},{"id":"zh-Play_Vo_Char_NPC027_struck_002-take-2","title":"Урон II · Запись 2","language":"Китайский","audioUrl":"/nte-meta/game-audio/437ce024305726b4b352.ogg","sourceUrl":"","description":"По мне попали…\n\n(Сяочжэнь: Тогда дай сдачи!)"},{"id":"en-Play_Vo_Char_NPC027_hp_003-take-2","title":"Низкий уровень здоровья III · Запись 2","language":"Английский","audioUrl":"/nte-meta/game-audio/80bf3fe6c0bceeb98dd6.ogg","sourceUrl":"","description":"(Сяочжэнь: Малявка, не подставляйся больше!)\n\nЯ… справлюсь!"},{"id":"ko-Play_Vo_Char_NPC027_hstruck_001-take-2","title":"Сильный урон I · Запись 2","language":"Корейский","audioUrl":"/nte-meta/game-audio/8c33b59303270f80854d.ogg","sourceUrl":"","description":"(Сяочжэнь: Тьфу, малявка?!)\n\nЯ… в порядке!"},{"id":"zh-Play_Vo_Char_NPC027_about_002-take-2","title":"О Хаосе · Запись 2","language":"Китайский","audioUrl":"/nte-meta/game-audio/dc98a5f947a8a384b892.ogg","sourceUrl":"","description":"У Хаоса частота жутко шумная — трещит без умолку, прямо как он сам. Его канал затихает, только когда он сталкивается с эсперами-преступниками. В такие моменты его сигнал грохочет и рычит, словно дикий зверь… Хоть мы и ходим вместе на миссии, часто разделяемся, потому что он вечно уходит в сторону, выслеживая цель… В смысле, очевидно же, что это он теряется, а я иду верным путём!\n\n(Сяочжэнь: Будь я на месте Хаоса, я бы прямо сейчас твой ахогэ с корнем вырвала!)"},{"id":"ja-Play_Vo_Char_NPC027_struck_001-take-2","title":"Урон I · Запись 2","language":"Японский","audioUrl":"/nte-meta/game-audio/13598ad28ac4a4dc5746.ogg","sourceUrl":"","description":"……\n\n(Сяочжэнь: Время платить по счетам!)"},{"id":"ko-Play_Vo_Char_NPC027_about_001-take-2","title":"О Нице · Запись 2","language":"Корейский","audioUrl":"/nte-meta/game-audio/475ed35ac88877fc2ee8.ogg","sourceUrl":"","description":"У Ницы частота очень ровная, как… фортепиано, которое играет строго по нотам, не упуская ни одной мелочи. Иногда её частота ускоряется, да так, что даже от одного прослушивания дух захватывает, но сама Ница безумно надёжная! Даже может слово в слово пересказать всё руководство по стандартным процедурам ТОИ. Вот только… она вечно пытается делать всё пошагово и исключительно по правилам. Стоит случиться чему-то непредвиденному, и она сразу начинает паниковать. Но не волнуйся, я её сенпай, так что обязательно за ней присмотрю!\n\n(Сяочжэнь: Ты же в курсе, что опережаешь её по стажу всего-то на полгода?…)"},{"id":"ko-Play_Vo_Char_NPC027_struck_001-take-2","title":"Урон I · Запись 2","language":"Корейский","audioUrl":"/nte-meta/game-audio/98b910d7efbca50f2aff.ogg","sourceUrl":"","description":"……\n\n(Сяочжэнь: Время платить по счетам!)"},{"id":"en-Play_Vo_Char_NPC027_ug_003-take-2","title":"Вознесение персонажа III · Запись 2","language":"Английский","audioUrl":"/nte-meta/game-audio/c7403a521326ae7210cf.ogg","sourceUrl":"","description":"Финальная эволюция Линко… Эм-м, во что бы мне эволюционировать… может, в Абсолютную Линко!\n\n(Сяочжэнь: Тебе никогда не бывает скучно…)"},{"id":"zh-Play_Vo_Char_NPC027_weather_003-take-2","title":"Холодно · Запись 2","language":"Китайский","audioUrl":"/nte-meta/game-audio/08790b9c9dbe859a33a3.ogg","sourceUrl":"","description":"Так холодно… Если бы только призрачное пламя Сяочжэнь могло меня согреть…\n\n(Сяочжэнь: А? И как я, по-твоему, это сделаю? Я же не какой-то там огненный дух!)"},{"id":"en-Play_Vo_Char_NPC027_greet_001-take-2","title":"Утреннее приветствие · Запись 2","language":"Английский","audioUrl":"/nte-meta/game-audio/6fa82926aa079f5712d4.ogg","sourceUrl":"","description":"Утречко, оценщик… Ох… Я вчера поздно легла, ха…\n\n(Сяочжэнь: Опять эта малявка засиделась допоздна. Даже призраки спать ложатся раньше…)Утречко, оценщица… Ох… Я вчера поздно легла, ха…\n\n(Сяочжэнь: Опять эта малявка засиделась допоздна. Даже призраки спать ложатся раньше…)"},{"id":"ko-Play_Vo_Char_NPC027_hp_003-take-2","title":"Низкий уровень здоровья III · Запись 2","language":"Корейский","audioUrl":"/nte-meta/game-audio/bf8ac3544a2309058f86.ogg","sourceUrl":"","description":"(Сяочжэнь: Малявка, не подставляйся больше!)\n\nЯ… справлюсь!"},{"id":"ko-Play_Vo_Char_NPC027_hstruck_002-take-2","title":"Сильный урон II · Запись 2","language":"Корейский","audioUrl":"/nte-meta/game-audio/e9b44dbfa1b5ae5c6471.ogg","sourceUrl":"","description":"Уф… нгх…\n\n(Сяочжэнь: Ах ты бандюга!)"},{"id":"en-Play_Vo_Char_NPC027_hp_001-take-2","title":"Низкий уровень здоровья I · Запись 2","language":"Английский","audioUrl":"/nte-meta/game-audio/32660776391b6d02e11e.ogg","sourceUrl":"","description":"Надо… собраться…\n\n(Сяочжэнь: Малявка, держись!)"},{"id":"zh-Play_Vo_Char_NPC027_hstruck_001-take-2","title":"Сильный урон I · Запись 2","language":"Китайский","audioUrl":"/nte-meta/game-audio/bb9efde446141a78a61a.ogg","sourceUrl":"","description":"(Сяочжэнь: Тьфу, малявка?!)\n\nЯ… в порядке!"},{"id":"ko-Play_Vo_Char_NPC027_about_002-take-2","title":"О Хаосе · Запись 2","language":"Корейский","audioUrl":"/nte-meta/game-audio/24625b4ceaba84404cbc.ogg","sourceUrl":"","description":"У Хаоса частота жутко шумная — трещит без умолку, прямо как он сам. Его канал затихает, только когда он сталкивается с эсперами-преступниками. В такие моменты его сигнал грохочет и рычит, словно дикий зверь… Хоть мы и ходим вместе на миссии, часто разделяемся, потому что он вечно уходит в сторону, выслеживая цель… В смысле, очевидно же, что это он теряется, а я иду верным путём!\n\n(Сяочжэнь: Будь я на месте Хаоса, я бы прямо сейчас твой ахогэ с корнем вырвала!)"},{"id":"ja-Play_Vo_Char_NPC027_weather_004-take-2","title":"Жарко · Запись 2","language":"Японский","audioUrl":"/nte-meta/game-audio/da081318d18def322561.ogg","sourceUrl":"","description":"Ну и жара… Вот бы обернуть Сяочжэнь вокруг шеи вместо шарфа, мне бы сразу полегчало… Сяо… чжэнь…\n\n(Сяочжэнь: Ни за что! Ни один призрак в такую жарищу не вылезет из своего телика!)"},{"id":"en-Play_Vo_Char_NPC027_hp_002-take-2","title":"Низкий уровень здоровья II · Запись 2","language":"Английский","audioUrl":"/nte-meta/game-audio/a04a8c8ec8dfe2e3579d.ogg","sourceUrl":"","description":"(Сяочжэнь: Эй, плохо дело!)\n\nЭто ещё… не конец!"},{"id":"ja-Play_Vo_Char_NPC027_about_001-take-2","title":"О Нице · Запись 2","language":"Японский","audioUrl":"/nte-meta/game-audio/273074204644979fdfad.ogg","sourceUrl":"","description":"У Ницы частота очень ровная, как… фортепиано, которое играет строго по нотам, не упуская ни одной мелочи. Иногда её частота ускоряется, да так, что даже от одного прослушивания дух захватывает, но сама Ница безумно надёжная! Даже может слово в слово пересказать всё руководство по стандартным процедурам ТОИ. Вот только… она вечно пытается делать всё пошагово и исключительно по правилам. Стоит случиться чему-то непредвиденному, и она сразу начинает паниковать. Но не волнуйся, я её сенпай, так что обязательно за ней присмотрю!\n\n(Сяочжэнь: Ты же в курсе, что опережаешь её по стажу всего-то на полгода?…)"},{"id":"ja-Play_Vo_Char_NPC027_hp_003-take-2","title":"Низкий уровень здоровья III · Запись 2","language":"Японский","audioUrl":"/nte-meta/game-audio/5a60ae485ba2f8ca889f.ogg","sourceUrl":"","description":"(Сяочжэнь: Малявка, не подставляйся больше!)\n\nЯ… справлюсь!"},{"id":"ja-Play_Vo_Char_NPC027_ug_003-take-2","title":"Вознесение персонажа III · Запись 2","language":"Японский","audioUrl":"/nte-meta/game-audio/4e81bbb8a041f13e227d.ogg","sourceUrl":"","description":"Финальная эволюция Линко… Эм-м, во что бы мне эволюционировать… может, в Абсолютную Линко!\n\n(Сяочжэнь: Тебе никогда не бывает скучно…)"},{"id":"en-Play_Vo_Char_NPC027_talk_002-take-2","title":"Тема: наушники · Запись 2","language":"Английский","audioUrl":"/nte-meta/game-audio/81916821d4d197d1988a.ogg","sourceUrl":"","description":"Бюро выдало мне эту модифицированную гарнитуру. Кажется, она называется… «Гарнитура с фильтром помех»? Я кручу этот регулятор, он убирает помехи и позволяет мне сфокусироваться на поиске конкретной частоты — прямо как на радио. А ещё её можно использовать как обычные наушники. Я слушаю через них рок, который выдают аномалии, сборники звуков всяких странностей или просто белый шум из аномальных измерений… ну, всё в таком духе. Да и качество звука просто отличное.\n\n(Сяочжэнь: Да что же за чертовщину ты слушаешь…)"},{"id":"ja-Play_Vo_Char_NPC027_hstruck_002-take-2","title":"Сильный урон II · Запись 2","language":"Японский","audioUrl":"/nte-meta/game-audio/075bc9be2cb72633317d.ogg","sourceUrl":"","description":"Уф… нгх…\n\n(Сяочжэнь: Ах ты бандюга!)"},{"id":"ko-Play_Vo_Char_NPC027_gift_003-take-2","title":"Подарок получен III · Запись 2","language":"Корейский","audioUrl":"/nte-meta/game-audio/f4e96270e83a5f6404e6.ogg","sourceUrl":"","description":"О, безграничные дары природы!\n\n(Сяочжэнь: Эй, это от оценщика вообще-то, а не от матушки природы.)О, безграничные дары природы!\n\n(Сяочжэнь: Эй, это от оценщицы вообще-то, а не от матушки природы.)"},{"id":"ko-Play_Vo_Char_NPC027_Parry_001-take-2","title":"Парирование I · Запись 2","language":"Корейский","audioUrl":"/nte-meta/game-audio/b103157f29406b5223e2.ogg","sourceUrl":"","description":"Карательная контратака!\n\n(Сяочжэнь: Что за игру ты затеяла на этот раз?..)"},{"id":"en-Play_Vo_Char_NPC027_hstruck_001-take-2","title":"Сильный урон I · Запись 2","language":"Английский","audioUrl":"/nte-meta/game-audio/5abeda39f9e07ebb7c22.ogg","sourceUrl":"","description":"(Сяочжэнь: Тьфу, малявка?!)\n\nЯ… в порядке!"},{"id":"ko-Play_Vo_Char_NPC027_self_002-take-2","title":"Обо мне: битва · Запись 2","language":"Корейский","audioUrl":"/nte-meta/game-audio/5fea1ccb5f299717e27c.ogg","sourceUrl":"","description":"Надеюсь, то, как мы с Сяочжэнь сражаемся плечом к плечу, тебя не пугает. Эти огромные руки на самом деле принадлежат ей. А как у нас это получается… если я достаточно синхронизируюсь с определённой частотой, то иногда могу войти в полный резонанс с её источником… Мы словно делимся эмоциями, чувствами, силами и действуем как одно целое… Похоже на какое-то состояние усиления? Правда, удерживать такое состояние трудно. Сейчас Сяочжэнь — единственная, с кем я могу поддерживать стабильный резонанс…\n\n(Сяочжэнь: А? Тебе меня мало, что ли? Иди спроси у тех гадов, которых ты повязала, как я их до чёртиков напугала! И этой малявке всё мало, пф-ф…)"},{"id":"en-Play_Vo_Char_NPC027_about_002-take-2","title":"О Хаосе · Запись 2","language":"Английский","audioUrl":"/nte-meta/game-audio/049d4ddd2a6f2c346e4e.ogg","sourceUrl":"","description":"У Хаоса частота жутко шумная — трещит без умолку, прямо как он сам. Его канал затихает, только когда он сталкивается с эсперами-преступниками. В такие моменты его сигнал грохочет и рычит, словно дикий зверь… Хоть мы и ходим вместе на миссии, часто разделяемся, потому что он вечно уходит в сторону, выслеживая цель… В смысле, очевидно же, что это он теряется, а я иду верным путём!\n\n(Сяочжэнь: Будь я на месте Хаоса, я бы прямо сейчас твой ахогэ с корнем вырвала!)"},{"id":"ko-Play_Vo_Char_NPC027_hp_001-take-2","title":"Низкий уровень здоровья I · Запись 2","language":"Корейский","audioUrl":"/nte-meta/game-audio/800436f3954bb5593758.ogg","sourceUrl":"","description":"Надо… собраться…\n\n(Сяочжэнь: Малявка, держись!)"},{"id":"zh-Play_Vo_Char_NPC027_about_001-take-2","title":"О Нице · Запись 2","language":"Китайский","audioUrl":"/nte-meta/game-audio/586ab7ab36e680a2f01f.ogg","sourceUrl":"","description":"У Ницы частота очень ровная, как… фортепиано, которое играет строго по нотам, не упуская ни одной мелочи. Иногда её частота ускоряется, да так, что даже от одного прослушивания дух захватывает, но сама Ница безумно надёжная! Даже может слово в слово пересказать всё руководство по стандартным процедурам ТОИ. Вот только… она вечно пытается делать всё пошагово и исключительно по правилам. Стоит случиться чему-то непредвиденному, и она сразу начинает паниковать. Но не волнуйся, я её сенпай, так что обязательно за ней присмотрю!\n\n(Сяочжэнь: Ты же в курсе, что опережаешь её по стажу всего-то на полгода?…)"},{"id":"en-Play_Vo_Char_NPC027_self_002-take-2","title":"Обо мне: битва · Запись 2","language":"Английский","audioUrl":"/nte-meta/game-audio/ce45a8f10919991f5666.ogg","sourceUrl":"","description":"Надеюсь, то, как мы с Сяочжэнь сражаемся плечом к плечу, тебя не пугает. Эти огромные руки на самом деле принадлежат ей. А как у нас это получается… если я достаточно синхронизируюсь с определённой частотой, то иногда могу войти в полный резонанс с её источником… Мы словно делимся эмоциями, чувствами, силами и действуем как одно целое… Похоже на какое-то состояние усиления? Правда, удерживать такое состояние трудно. Сейчас Сяочжэнь — единственная, с кем я могу поддерживать стабильный резонанс…\n\n(Сяочжэнь: А? Тебе меня мало, что ли? Иди спроси у тех гадов, которых ты повязала, как я их до чёртиков напугала! И этой малявке всё мало, пф-ф…)"},{"id":"ja-Play_Vo_Char_NPC027_TeammateDown_001-take-2","title":"Поражен товарищ по команде – Ноль · Запись 2","language":"Японский","audioUrl":"/nte-meta/game-audio/69b2bca4f59ad2245f10.ogg","sourceUrl":"","description":"Сигнал оценщика… пропал…\n\n(Сяочжэнь: Малявка! Соберись!)Сигнал оценщицы… пропал…\n\n(Сяочжэнь: Малявка! Соберись!)"},{"id":"ko-Play_Vo_Char_NPC027_greet_001-take-2","title":"Утреннее приветствие · Запись 2","language":"Корейский","audioUrl":"/nte-meta/game-audio/8de86fb91cd5af03e551.ogg","sourceUrl":"","description":"Утречко, оценщик… Ох… Я вчера поздно легла, ха…\n\n(Сяочжэнь: Опять эта малявка засиделась допоздна. Даже призраки спать ложатся раньше…)Утречко, оценщица… Ох… Я вчера поздно легла, ха…\n\n(Сяочжэнь: Опять эта малявка засиделась допоздна. Даже призраки спать ложатся раньше…)"},{"id":"ko-Play_Vo_Char_NPC027_talk_002-take-2","title":"Тема: наушники · Запись 2","language":"Корейский","audioUrl":"/nte-meta/game-audio/3389b0a1fb6315fa82b5.ogg","sourceUrl":"","description":"Бюро выдало мне эту модифицированную гарнитуру. Кажется, она называется… «Гарнитура с фильтром помех»? Я кручу этот регулятор, он убирает помехи и позволяет мне сфокусироваться на поиске конкретной частоты — прямо как на радио. А ещё её можно использовать как обычные наушники. Я слушаю через них рок, который выдают аномалии, сборники звуков всяких странностей или просто белый шум из аномальных измерений… ну, всё в таком духе. Да и качество звука просто отличное.\n\n(Сяочжэнь: Да что же за чертовщину ты слушаешь…)"},{"id":"en-Play_Vo_Char_NPC027_hobby_001-take-2","title":"Хобби · Запись 2","language":"Английский","audioUrl":"/nte-meta/game-audio/41a2cfa8661c5215ccaa.ogg","sourceUrl":"","description":"У меня дома есть огромный шкаф, забитый дисками с фильмами. Каждый вечер я наугад выбираю один и смотрю вместе с Сяочжэнь. Я обожаю всякое про пришельцев и паранормальщину, а вот Сяочжэнь такое терпеть не может. Она всегда ворчит: зачем смотреть на фальшивые спецэффекты, если она сама — самый что ни на есть настоящий дух…\n\n(Сяочжэнь: Пф-ф! Если меня, злого духа, когда-нибудь возьмут на роль злодея, фильм сразу станет в тысячу раз страшнее!)"},{"id":"ja-Play_Vo_Char_NPC027_hstruck_001-take-2","title":"Сильный урон I · Запись 2","language":"Японский","audioUrl":"/nte-meta/game-audio/c722126366d15116071d.ogg","sourceUrl":"","description":"(Сяочжэнь: Тьфу, малявка?!)\n\nЯ… в порядке!"},{"id":"en-Play_Vo_Char_NPC027_gift_003-take-2","title":"Подарок получен III · Запись 2","language":"Английский","audioUrl":"/nte-meta/game-audio/7550635b0b42a0124653.ogg","sourceUrl":"","description":"О, безграничные дары природы!\n\n(Сяочжэнь: Эй, это от оценщика вообще-то, а не от матушки природы.)О, безграничные дары природы!\n\n(Сяочжэнь: Эй, это от оценщицы вообще-то, а не от матушки природы.)"},{"id":"zh-Play_Vo_Char_NPC027_hp_002-take-2","title":"Низкий уровень здоровья II · Запись 2","language":"Китайский","audioUrl":"/nte-meta/game-audio/47751dfd631723c6bcf3.ogg","sourceUrl":"","description":"(Сяочжэнь: Эй, плохо дело!)\n\nЭто ещё… не конец!"},{"id":"ja-Play_Vo_Char_NPC027_hp_002-take-2","title":"Низкий уровень здоровья II · Запись 2","language":"Японский","audioUrl":"/nte-meta/game-audio/18ff9810b97bf51d214a.ogg","sourceUrl":"","description":"(Сяочжэнь: Эй, плохо дело!)\n\nЭто ещё… не конец!"},{"id":"ko-Play_Vo_Char_NPC027_TeammateDown_001-take-2","title":"Поражен товарищ по команде – Ноль · Запись 2","language":"Корейский","audioUrl":"/nte-meta/game-audio/f70c993fc5e7fd7ac699.ogg","sourceUrl":"","description":"Сигнал оценщика… пропал…\n\n(Сяочжэнь: Малявка! Соберись!)Сигнал оценщицы… пропал…\n\n(Сяочжэнь: Малявка! Соберись!)"},{"id":"zh-Play_Vo_Char_NPC027_hp_001-take-2","title":"Низкий уровень здоровья I · Запись 2","language":"Китайский","audioUrl":"/nte-meta/game-audio/ed3826b46a6ffdc28042.ogg","sourceUrl":"","description":"Надо… собраться…\n\n(Сяочжэнь: Малявка, держись!)"},{"id":"ko-Play_Vo_Char_NPC027_struck_002-take-2","title":"Урон II · Запись 2","language":"Корейский","audioUrl":"/nte-meta/game-audio/4e1d6ab87bfe43370245.ogg","sourceUrl":"","description":"По мне попали…\n\n(Сяочжэнь: Тогда дай сдачи!)"},{"id":"zh-Play_Vo_Char_NPC027_self_002-take-2","title":"Обо мне: битва · Запись 2","language":"Китайский","audioUrl":"/nte-meta/game-audio/f13ca362b24d1a534d94.ogg","sourceUrl":"","description":"Надеюсь, то, как мы с Сяочжэнь сражаемся плечом к плечу, тебя не пугает. Эти огромные руки на самом деле принадлежат ей. А как у нас это получается… если я достаточно синхронизируюсь с определённой частотой, то иногда могу войти в полный резонанс с её источником… Мы словно делимся эмоциями, чувствами, силами и действуем как одно целое… Похоже на какое-то состояние усиления? Правда, удерживать такое состояние трудно. Сейчас Сяочжэнь — единственная, с кем я могу поддерживать стабильный резонанс…\n\n(Сяочжэнь: А? Тебе меня мало, что ли? Иди спроси у тех гадов, которых ты повязала, как я их до чёртиков напугала! И этой малявке всё мало, пф-ф…)"},{"id":"zh-Play_Vo_Char_NPC027_greet_001-take-2","title":"Утреннее приветствие · Запись 2","language":"Китайский","audioUrl":"/nte-meta/game-audio/69b8c3c35ef38e34f729.ogg","sourceUrl":"","description":"Утречко, оценщик… Ох… Я вчера поздно легла, ха…\n\n(Сяочжэнь: Опять эта малявка засиделась допоздна. Даже призраки спать ложатся раньше…)Утречко, оценщица… Ох… Я вчера поздно легла, ха…\n\n(Сяочжэнь: Опять эта малявка засиделась допоздна. Даже призраки спать ложатся раньше…)"},{"id":"ja-Play_Vo_Char_NPC027_ug_002-take-2","title":"Вознесение персонажа II · Запись 2","language":"Японский","audioUrl":"/nte-meta/game-audio/a4526ea5626095c45a15.ogg","sourceUrl":"","description":"Что? Линко… эволюционирует!\n\n(Сяочжэнь: Она эволюционирует! Только в обратную сторону.)"},{"id":"zh-Play_Vo_Char_NPC027_Parry_001-take-2","title":"Парирование I · Запись 2","language":"Китайский","audioUrl":"/nte-meta/game-audio/ffe2fb6d8bdcb5ec0140.ogg","sourceUrl":"","description":"Карательная контратака!\n\n(Сяочжэнь: Что за игру ты затеяла на этот раз?..)"},{"id":"ja-Play_Vo_Char_NPC027_about_002-take-2","title":"О Хаосе · Запись 2","language":"Японский","audioUrl":"/nte-meta/game-audio/99f785315a3e9f8aa293.ogg","sourceUrl":"","description":"У Хаоса частота жутко шумная — трещит без умолку, прямо как он сам. Его канал затихает, только когда он сталкивается с эсперами-преступниками. В такие моменты его сигнал грохочет и рычит, словно дикий зверь… Хоть мы и ходим вместе на миссии, часто разделяемся, потому что он вечно уходит в сторону, выслеживая цель… В смысле, очевидно же, что это он теряется, а я иду верным путём!\n\n(Сяочжэнь: Будь я на месте Хаоса, я бы прямо сейчас твой ахогэ с корнем вырвала!)"},{"id":"en-Play_Vo_Char_NPC027_about_001-take-2","title":"О Нице · Запись 2","language":"Английский","audioUrl":"/nte-meta/game-audio/bd5fa62fcc79ca22e1d7.ogg","sourceUrl":"","description":"У Ницы частота очень ровная, как… фортепиано, которое играет строго по нотам, не упуская ни одной мелочи. Иногда её частота ускоряется, да так, что даже от одного прослушивания дух захватывает, но сама Ница безумно надёжная! Даже может слово в слово пересказать всё руководство по стандартным процедурам ТОИ. Вот только… она вечно пытается делать всё пошагово и исключительно по правилам. Стоит случиться чему-то непредвиденному, и она сразу начинает паниковать. Но не волнуйся, я её сенпай, так что обязательно за ней присмотрю!\n\n(Сяочжэнь: Ты же в курсе, что опережаешь её по стажу всего-то на полгода?…)"},{"id":"ja-Play_Vo_Char_NPC027_hobby_001-take-2","title":"Хобби · Запись 2","language":"Японский","audioUrl":"/nte-meta/game-audio/88268fa05d6461207ed2.ogg","sourceUrl":"","description":"У меня дома есть огромный шкаф, забитый дисками с фильмами. Каждый вечер я наугад выбираю один и смотрю вместе с Сяочжэнь. Я обожаю всякое про пришельцев и паранормальщину, а вот Сяочжэнь такое терпеть не может. Она всегда ворчит: зачем смотреть на фальшивые спецэффекты, если она сама — самый что ни на есть настоящий дух…\n\n(Сяочжэнь: Пф-ф! Если меня, злого духа, когда-нибудь возьмут на роль злодея, фильм сразу станет в тысячу раз страшнее!)"},{"id":"en-Play_Vo_Char_NPC027_weather_003-take-2","title":"Холодно · Запись 2","language":"Английский","audioUrl":"/nte-meta/game-audio/e2d72427d1fdaeedcdfa.ogg","sourceUrl":"","description":"Так холодно… Если бы только призрачное пламя Сяочжэнь могло меня согреть…\n\n(Сяочжэнь: А? И как я, по-твоему, это сделаю? Я же не какой-то там огненный дух!)"},{"id":"ja-Play_Vo_Char_NPC027_self_002-take-2","title":"Обо мне: битва · Запись 2","language":"Японский","audioUrl":"/nte-meta/game-audio/c093b46c7ccb2ab77ec7.ogg","sourceUrl":"","description":"Надеюсь, то, как мы с Сяочжэнь сражаемся плечом к плечу, тебя не пугает. Эти огромные руки на самом деле принадлежат ей. А как у нас это получается… если я достаточно синхронизируюсь с определённой частотой, то иногда могу войти в полный резонанс с её источником… Мы словно делимся эмоциями, чувствами, силами и действуем как одно целое… Похоже на какое-то состояние усиления? Правда, удерживать такое состояние трудно. Сейчас Сяочжэнь — единственная, с кем я могу поддерживать стабильный резонанс…\n\n(Сяочжэнь: А? Тебе меня мало, что ли? Иди спроси у тех гадов, которых ты повязала, как я их до чёртиков напугала! И этой малявке всё мало, пф-ф…)"},{"id":"zh-Play_Vo_Char_NPC027_gift_003-take-2","title":"Подарок получен III · Запись 2","language":"Китайский","audioUrl":"/nte-meta/game-audio/d4867755d7722d64967a.ogg","sourceUrl":"","description":"О, безграничные дары природы!\n\n(Сяочжэнь: Эй, это от оценщика вообще-то, а не от матушки природы.)О, безграничные дары природы!\n\n(Сяочжэнь: Эй, это от оценщицы вообще-то, а не от матушки природы.)"},{"id":"en-Play_Vo_Char_NPC027_weather_004-take-2","title":"Жарко · Запись 2","language":"Английский","audioUrl":"/nte-meta/game-audio/1d0485b10015ce467bd4.ogg","sourceUrl":"","description":"Ну и жара… Вот бы обернуть Сяочжэнь вокруг шеи вместо шарфа, мне бы сразу полегчало… Сяо… чжэнь…\n\n(Сяочжэнь: Ни за что! Ни один призрак в такую жарищу не вылезет из своего телика!)"},{"id":"ja-Play_Vo_Char_NPC027_weather_003-take-2","title":"Холодно · Запись 2","language":"Японский","audioUrl":"/nte-meta/game-audio/c7aeb830605ff164731e.ogg","sourceUrl":"","description":"Так холодно… Если бы только призрачное пламя Сяочжэнь могло меня согреть…\n\n(Сяочжэнь: А? И как я, по-твоему, это сделаю? Я же не какой-то там огненный дух!)"},{"id":"zh-Play_Vo_Char_NPC027_talk_002-take-2","title":"Тема: наушники · Запись 2","language":"Китайский","audioUrl":"/nte-meta/game-audio/767f7dc2802374cef61a.ogg","sourceUrl":"","description":"Бюро выдало мне эту модифицированную гарнитуру. Кажется, она называется… «Гарнитура с фильтром помех»? Я кручу этот регулятор, он убирает помехи и позволяет мне сфокусироваться на поиске конкретной частоты — прямо как на радио. А ещё её можно использовать как обычные наушники. Я слушаю через них рок, который выдают аномалии, сборники звуков всяких странностей или просто белый шум из аномальных измерений… ну, всё в таком духе. Да и качество звука просто отличное.\n\n(Сяочжэнь: Да что же за чертовщину ты слушаешь…)"},{"id":"en-Play_Vo_Char_NPC027_hstruck_002-take-2","title":"Сильный урон II · Запись 2","language":"Английский","audioUrl":"/nte-meta/game-audio/17f99c67ba6bc44e4d40.ogg","sourceUrl":"","description":"Уф… нгх…\n\n(Сяочжэнь: Ах ты бандюга!)"},{"id":"zh-Play_Vo_Char_NPC027_ug_002-take-2","title":"Вознесение персонажа II · Запись 2","language":"Китайский","audioUrl":"/nte-meta/game-audio/58928b2e68c936134596.ogg","sourceUrl":"","description":"Что? Линко… эволюционирует!\n\n(Сяочжэнь: Она эволюционирует! Только в обратную сторону.)"},{"id":"ja-Play_Vo_Char_NPC027_greet_001-take-2","title":"Утреннее приветствие · Запись 2","language":"Японский","audioUrl":"/nte-meta/game-audio/84272a6e87b8cd05d544.ogg","sourceUrl":"","description":"Утречко, оценщик… Ох… Я вчера поздно легла, ха…\n\n(Сяочжэнь: Опять эта малявка засиделась допоздна. Даже призраки спать ложатся раньше…)Утречко, оценщица… Ох… Я вчера поздно легла, ха…\n\n(Сяочжэнь: Опять эта малявка засиделась допоздна. Даже призраки спать ложатся раньше…)"},{"id":"ja-Play_Vo_Char_NPC027_struck_002-take-2","title":"Урон II · Запись 2","language":"Японский","audioUrl":"/nte-meta/game-audio/24900f047db1c51f6b12.ogg","sourceUrl":"","description":"По мне попали…\n\n(Сяочжэнь: Тогда дай сдачи!)"},{"id":"zh-Play_Vo_Char_NPC027_hobby_001-take-2","title":"Хобби · Запись 2","language":"Китайский","audioUrl":"/nte-meta/game-audio/8784f43669d339f80d10.ogg","sourceUrl":"","description":"У меня дома есть огромный шкаф, забитый дисками с фильмами. Каждый вечер я наугад выбираю один и смотрю вместе с Сяочжэнь. Я обожаю всякое про пришельцев и паранормальщину, а вот Сяочжэнь такое терпеть не может. Она всегда ворчит: зачем смотреть на фальшивые спецэффекты, если она сама — самый что ни на есть настоящий дух…\n\n(Сяочжэнь: Пф-ф! Если меня, злого духа, когда-нибудь возьмут на роль злодея, фильм сразу станет в тысячу раз страшнее!)"},{"id":"en-Play_Vo_Char_NPC027_ug_002-take-2","title":"Вознесение персонажа II · Запись 2","language":"Английский","audioUrl":"/nte-meta/game-audio/a3a2d10aca9adb9957f7.ogg","sourceUrl":"","description":"Что? Линко… эволюционирует!\n\n(Сяочжэнь: Она эволюционирует! Только в обратную сторону.)"},{"id":"ja-Play_Vo_Char_NPC027_Parry_001-take-2","title":"Парирование I · Запись 2","language":"Японский","audioUrl":"/nte-meta/game-audio/9210849818b776c7d6d1.ogg","sourceUrl":"","description":"Карательная контратака!\n\n(Сяочжэнь: Что за игру ты затеяла на этот раз?..)"},{"id":"en-Play_Vo_Char_NPC027_struck_001-take-2","title":"Урон I · Запись 2","language":"Английский","audioUrl":"/nte-meta/game-audio/2d3abe3d91b6b0bc456d.ogg","sourceUrl":"","description":"……\n\n(Сяочжэнь: Время платить по счетам!)"},{"id":"ja-Play_Vo_Char_NPC027_talk_002-take-2","title":"Тема: наушники · Запись 2","language":"Японский","audioUrl":"/nte-meta/game-audio/35eefa526ac808d179da.ogg","sourceUrl":"","description":"Бюро выдало мне эту модифицированную гарнитуру. Кажется, она называется… «Гарнитура с фильтром помех»? Я кручу этот регулятор, он убирает помехи и позволяет мне сфокусироваться на поиске конкретной частоты — прямо как на радио. А ещё её можно использовать как обычные наушники. Я слушаю через них рок, который выдают аномалии, сборники звуков всяких странностей или просто белый шум из аномальных измерений… ну, всё в таком духе. Да и качество звука просто отличное.\n\n(Сяочжэнь: Да что же за чертовщину ты слушаешь…)"},{"id":"zh-Play_Vo_Char_NPC027_weather_004-take-2","title":"Жарко · Запись 2","language":"Китайский","audioUrl":"/nte-meta/game-audio/03e726ae854d1ea6eca5.ogg","sourceUrl":"","description":"Ну и жара… Вот бы обернуть Сяочжэнь вокруг шеи вместо шарфа, мне бы сразу полегчало… Сяо… чжэнь…\n\n(Сяочжэнь: Ни за что! Ни один призрак в такую жарищу не вылезет из своего телика!)"},{"id":"en-Play_Vo_Char_NPC027_Parry_001-take-2","title":"Парирование I · Запись 2","language":"Английский","audioUrl":"/nte-meta/game-audio/ae3a49581d439097e65b.ogg","sourceUrl":"","description":"Карательная контратака!\n\n(Сяочжэнь: Что за игру ты затеяла на этот раз?..)"},{"id":"ko-Play_Vo_Char_NPC027_ug_002-take-2","title":"Вознесение персонажа II · Запись 2","language":"Корейский","audioUrl":"/nte-meta/game-audio/426f6509ddbc95c53537.ogg","sourceUrl":"","description":"Что? Линко… эволюционирует!\n\n(Сяочжэнь: Она эволюционирует! Только в обратную сторону.)"},{"id":"zh-Play_Vo_Char_NPC027_TeammateDown_001-take-2","title":"Поражен товарищ по команде – Ноль · Запись 2","language":"Китайский","audioUrl":"/nte-meta/game-audio/c3623a78e4175046d58d.ogg","sourceUrl":"","description":"Сигнал оценщика… пропал…\n\n(Сяочжэнь: Малявка! Соберись!)Сигнал оценщицы… пропал…\n\n(Сяочжэнь: Малявка! Соберись!)"},{"id":"ko-Play_Vo_Char_NPC027_weather_003-take-2","title":"Холодно · Запись 2","language":"Корейский","audioUrl":"/nte-meta/game-audio/cedd6bf1e0552f5651d1.ogg","sourceUrl":"","description":"Так холодно… Если бы только призрачное пламя Сяочжэнь могло меня согреть…\n\n(Сяочжэнь: А? И как я, по-твоему, это сделаю? Я же не какой-то там огненный дух!)"}]') incoming WHERE NOT EXISTS(SELECT 1 FROM json_each(voice_lines_json) old WHERE json_extract(old.value,'$.id')=json_extract(incoming.value,'$.id')))) WHERE character_id='linko' AND updated_at<='2026-11-06 02:38:24' AND EXISTS(SELECT 1 FROM characters WHERE id=character_id AND updated_at='2026-10-21 03:56:00');
UPDATE character_profiles SET voice_lines_json=(SELECT json_group_array(json(value)) FROM (SELECT value FROM json_each(voice_lines_json) UNION ALL SELECT incoming.value FROM json_each('[{"id":"en-Play_Vo_Char_NPC008_windfall_004-take-2","title":"Неожиданная добыча IV · Запись 2","language":"Английский","audioUrl":"/nte-meta/game-audio/1b5447a2812721130472.ogg","sourceUrl":"","description":"Тебе крышка, если это съешь! (Кирумару: Эх…)"},{"id":"ja-Play_Vo_Char_NPC008_windfall_004-take-2","title":"Неожиданная добыча IV · Запись 2","language":"Японский","audioUrl":"/nte-meta/game-audio/b223d0a4e8d0f2e97c4e.ogg","sourceUrl":"","description":"Тебе крышка, если это съешь! (Кирумару: Эх…)"},{"id":"zh-Play_Vo_Char_NPC008_windfall_004-take-2","title":"Неожиданная добыча IV · Запись 2","language":"Китайский","audioUrl":"/nte-meta/game-audio/bf5bbd6be248bae6afdb.ogg","sourceUrl":"","description":"Тебе крышка, если это съешь! (Кирумару: Эх…)"},{"id":"ko-Play_Vo_Char_NPC008_windfall_004-take-2","title":"Неожиданная добыча IV · Запись 2","language":"Корейский","audioUrl":"/nte-meta/game-audio/9942c3cc061b81b8c1ee.ogg","sourceUrl":"","description":"Тебе крышка, если это съешь! (Кирумару: Эх…)"}]') incoming WHERE NOT EXISTS(SELECT 1 FROM json_each(voice_lines_json) old WHERE json_extract(old.value,'$.id')=json_extract(incoming.value,'$.id')))) WHERE character_id='sakiri' AND updated_at<='2026-11-06 02:38:24' AND EXISTS(SELECT 1 FROM characters WHERE id=character_id AND updated_at='2026-07-02 18:37:34');
